<div class="admin-heading"><div><p class="eyebrow">LA MÉMOIRE DU CODEX</p><h1>Historique<span>.</span></h1><p class="admin-intro">Actions enregistrées avec leur responsable. Aucun mot de passe ni jeton n’est journalisé.</p></div></div><section class="admin-panel neu-flat"><div class="table-scroll"><table><thead><tr><th>Date (UTC)</th><th>Responsable</th><th>Action</th><th>Entité</th><th>Détails</th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= e($record['created_at']) ?></td><td><?= e($record['username'] ?? 'CLI / compte supprimé') ?></td><td><?= e($record['action']) ?></td><td><?= e($record['entity_type']) ?> #<?= e($record['entity_id']) ?></td><td><details><summary>Avant / après</summary><pre><?= e(json_encode(['avant'=>json_decode($record['old_values'] ?? 'null',true),'après'=>json_decode($record['new_values'] ?? 'null',true)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$records): ?><p>Aucune opération sur cette page.</p><?php endif; ?><div class="history-pagination"><?php if ($pageNumber>1): ?><a class="secondary-button" href="/admin/history?page=<?= $pageNumber-1 ?>">← Précédente</a><?php endif; ?><span>Page <?= $pageNumber ?></span><?php if (count($records)===50): ?><a class="secondary-button" href="/admin/history?page=<?= $pageNumber+1 ?>">Suivante →</a><?php endif; ?></div></section>
